def _text(text):
    return NS(content=[NS(type="thinking", thinking=""), NS(type="text", text=text)],
              stop_reason="end_turn")


def _create(*, model, max_tokens, messages, system=None, tools=None, **kwargs):
    if tools is not None:
        if len(messages) == 1:
            call = NS(type="tool_use", id="toolu_01", name="list_merged_prs", input={})
            return NS(content=[call], stop_reason="tool_use")
